 collection:'<path d="M5 7h14l2 5-9 9-9-9zM5 7l7 14 7-14M3 12h18"/>',
 finance:'<path d="M5 3h14v18H5zM8 7h8M8 11h8M8 15h3M14 15h2"/>',
